import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { getTheme, STATUS_COLORS } from '../utils/theme';
import { Icons } from '../utils/icons';
import SearchBar from '../components/common/SearchBar';
import Badge from '../components/common/Badge';

const TABS = [
  { key: 'note',  label: 'Notes',          icon: <Icons.Book /> },
  { key: 'paper', label: 'Papers',          icon: <Icons.FileText /> },
  { key: 'video', label: 'Videos',          icon: <Icons.Video /> },
  { key: 'doubt', label: 'Doubt Sessions',  icon: <Icons.MessageCircle /> },
];

export default function Resources() {
  const { selectedCollege, resources, dark, toast } = useApp();
  const css = getTheme(dark);
  const [tab, setTab]       = useState('note');
  const [search, setSearch] = useState('');
  const [subject, setSubject] = useState('all');

  const subjects = ['all', ...new Set(resources.map((r) => r.subject))];

  const filtered = resources.filter((r) => {
    const matchType    = r.type === tab;
    const matchCollege = !selectedCollege || r.college === selectedCollege.id;
    const matchSearch  = r.title.toLowerCase().includes(search.toLowerCase()) ||
                         r.subject.toLowerCase().includes(search.toLowerCase());
    const matchSubject = subject === 'all' || r.subject === subject;
    return matchType && matchCollege && matchSearch && matchSubject;
  });

  return (
    <div className="fade-in">
      {/* Header */}
      <div style={{ marginBottom: 24 }}>
        <h1 style={{ fontSize: 26, fontWeight: 800, letterSpacing: '-1px', color: dark ? '#fff' : '#0f0f23', marginBottom: 4 }}>
          {selectedCollege ? `${selectedCollege.short} Resources` : 'All Resources'}
        </h1>
        <p style={{ color: dark ? '#64748b' : '#94a3b8' }}>
          {selectedCollege ? selectedCollege.name : 'Browse all study materials across colleges'}
        </p>
      </div>

      {/* Tabs */}
      <div
        style={{
          display: 'flex', gap: 4, padding: 6, borderRadius: 13,
          background: dark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.04)',
          marginBottom: 24, width: 'fit-content',
        }}
      >
        {TABS.map((t) => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            style={{
              display: 'flex', alignItems: 'center', gap: 7,
              padding: '9px 18px', borderRadius: 9, border: 'none',
              background: tab === t.key ? (dark ? '#1e293b' : '#fff') : 'transparent',
              color: tab === t.key ? (dark ? '#f1f5f9' : '#0f0f23') : (dark ? '#64748b' : '#94a3b8'),
              fontWeight: tab === t.key ? 600 : 500, fontSize: 13, cursor: 'pointer',
              boxShadow: tab === t.key ? (dark ? '0 2px 10px rgba(0,0,0,0.3)' : '0 2px 8px rgba(0,0,0,0.08)') : 'none',
              transition: 'all 0.15s', fontFamily: 'inherit',
            }}
          >
            {t.icon} {t.label}
          </button>
        ))}
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 24, flexWrap: 'wrap', alignItems: 'center' }}>
        <SearchBar value={search} onChange={setSearch} placeholder="Search resources..." maxWidth={340} />
        <select
          value={subject}
          onChange={(e) => setSubject(e.target.value)}
          style={{ ...css.input, width: 'auto', minWidth: 140 }}
        >
          {subjects.map((s) => (
            <option key={s} value={s}>{s === 'all' ? 'All Subjects' : s}</option>
          ))}
        </select>
        <span style={{ fontSize: 13, color: dark ? '#475569' : '#94a3b8' }}>
          {filtered.length} result{filtered.length !== 1 ? 's' : ''}
        </span>
      </div>

      {/* Cards */}
      {filtered.length === 0 ? (
        <Empty />
      ) : tab === 'doubt' ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          {filtered.map((r) => <DoubtCard key={r.id} r={r} onAction={() => toast('Session registered! 🎉')} />)}
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(300px,1fr))', gap: 18 }}>
          {filtered.map((r) => <ResourceCard key={r.id} r={r} tab={tab} onAction={() => toast(tab === 'video' ? 'Opening video...' : 'Downloading...')} />)}
        </div>
      )}
    </div>
  );
}

/* ─── Empty State ─── */
function Empty() {
  const { dark } = useApp();
  return (
    <div style={{ textAlign: 'center', padding: '72px 0', color: dark ? '#475569' : '#94a3b8' }}>
      <div style={{ fontSize: 52, marginBottom: 14 }}>🔍</div>
      <p style={{ fontSize: 16, fontWeight: 600 }}>No resources found</p>
      <p style={{ fontSize: 13, marginTop: 5 }}>Try changing your filters or search query</p>
    </div>
  );
}

/* ─── Resource Card (note / paper / video) ─── */
function ResourceCard({ r, tab, onAction }) {
  const { dark } = useApp();
  const css = getTheme(dark);

  return (
    <div
      className="card-hover"
      style={{ ...css.card, padding: 22, borderRadius: 18, display: 'flex', flexDirection: 'column', gap: 0 }}
      onMouseEnter={(e) => (e.currentTarget.style.boxShadow = dark ? '0 14px 40px rgba(0,0,0,0.4)' : '0 14px 40px rgba(0,0,0,0.1)')}
      onMouseLeave={(e) => (e.currentTarget.style.boxShadow = '')}
    >
      {/* Video thumbnail */}
      {tab === 'video' && (
        <div
          style={{
            height: 126, borderRadius: 12, marginBottom: 16,
            background: 'linear-gradient(135deg,#0f0f23,#1a1a3e)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            position: 'relative', overflow: 'hidden',
          }}
        >
          <span style={{ fontSize: 52 }}>{r.thumbnail}</span>
          <div style={{
            position: 'absolute', inset: 0, display: 'flex',
            alignItems: 'center', justifyContent: 'center',
          }}>
            <div style={{
              width: 46, height: 46, borderRadius: '50%',
              background: 'rgba(99,102,241,0.9)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              color: '#fff', boxShadow: '0 4px 16px rgba(99,102,241,0.5)',
            }}>
              <Icons.Play />
            </div>
          </div>
          {r.duration && (
            <span style={{
              position: 'absolute', bottom: 8, right: 8,
              fontSize: 11, padding: '2px 8px', borderRadius: 6,
              background: 'rgba(0,0,0,0.75)', color: '#fff', fontWeight: 700,
            }}>{r.duration}</span>
          )}
        </div>
      )}

      {/* Badges */}
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 10 }}>
        <Badge label={r.subject} color="#6366f1" />
        {r.exam && <Badge label={r.exam} color="#10b981" />}
        {r.year && <Badge label={String(r.year)} color="#f59e0b" size="xs" />}
      </div>

      <h3 style={{ fontSize: 15, fontWeight: 700, color: dark ? '#f1f5f9' : '#0f0f23', lineHeight: 1.35, marginBottom: 7 }}>
        {r.title}
      </h3>
      <p style={{ fontSize: 12, color: dark ? '#475569' : '#94a3b8', marginBottom: 12 }}>
        by {r.uploadedBy} &nbsp;·&nbsp; {r.date}
        {r.size ? ` · ${r.size}` : ''}
        {r.pages ? ` · ${r.pages} pages` : ''}
      </p>

      {/* Tags */}
      {r.tags && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, marginBottom: 14 }}>
          {r.tags.map((tag) => (
            <span key={tag} style={{
              fontSize: 11, padding: '2px 8px', borderRadius: 6,
              background: dark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)',
              color: dark ? '#64748b' : '#94a3b8',
            }}>#{tag}</span>
          ))}
        </div>
      )}

      {/* Footer */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 'auto' }}>
        <span style={{ fontSize: 12, color: dark ? '#334155' : '#94a3b8' }}>
          {r.downloads != null && `⬇ ${r.downloads.toLocaleString()}`}
          {r.views != null && `👁 ${r.views.toLocaleString()}`}
        </span>
        <button
          onClick={onAction}
          style={{
            ...css.btnPrimary, fontSize: 12, padding: '7px 14px',
            display: 'flex', alignItems: 'center', gap: 6,
          }}
        >
          {tab === 'video' ? <><Icons.Play /> Watch</> : <><Icons.Download /> Download</>}
        </button>
      </div>
    </div>
  );
}

/* ─── Doubt Session Card ─── */
function DoubtCard({ r, onAction }) {
  const { dark } = useApp();
  const css = getTheme(dark);
  const statusColor = STATUS_COLORS[r.status] || '#64748b';
  const pct = Math.round((r.registered / r.seats) * 100);

  return (
    <div style={{ ...css.card, padding: 24, borderRadius: 18 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 18, flexWrap: 'wrap' }}>
        <div style={{
          width: 56, height: 56, borderRadius: 16,
          background: 'rgba(99,102,241,0.14)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: 28, flexShrink: 0,
        }}>🙋</div>

        <div style={{ flex: 1, minWidth: 200 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap', marginBottom: 6 }}>
            <h3 style={{ fontSize: 15, fontWeight: 700, color: dark ? '#f1f5f9' : '#0f0f23' }}>
              {r.title}
            </h3>
            <Badge label={r.status} color={statusColor} />
            <Badge label={r.subject} color="#6366f1" />
          </div>
          <div style={{ display: 'flex', gap: 18, fontSize: 12, color: dark ? '#64748b' : '#94a3b8', flexWrap: 'wrap' }}>
            <span>📅 {r.date}</span>
            <span>⏰ {r.time}</span>
            <span>⏱ {r.duration}</span>
            <span>👤 by {r.uploadedBy}</span>
          </div>

          {/* Seat progress */}
          <div style={{ marginTop: 10 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
              <span style={{ fontSize: 11, color: dark ? '#475569' : '#94a3b8' }}>
                {r.registered}/{r.seats} seats filled
              </span>
              <span style={{ fontSize: 11, color: statusColor, fontWeight: 600 }}>{pct}%</span>
            </div>
            <div style={{ height: 5, borderRadius: 100, background: dark ? '#1e293b' : '#e2e8f0', overflow: 'hidden' }}>
              <div style={{
                width: `${pct}%`, height: '100%', borderRadius: 100,
                background: pct >= 100 ? '#ef4444' : 'linear-gradient(90deg,#6366f1,#8b5cf6)',
                transition: 'width 0.4s ease',
              }} />
            </div>
          </div>
        </div>

        {r.status === 'upcoming' && (
          <button
            onClick={onAction}
            style={{ ...css.btnPrimary, fontSize: 13, padding: '10px 22px', flexShrink: 0 }}
          >
            Register
          </button>
        )}
        {r.status === 'full' && (
          <button disabled style={{
            fontSize: 13, padding: '10px 22px', borderRadius: 10,
            background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.3)',
            color: '#ef4444', cursor: 'not-allowed', fontWeight: 600, flexShrink: 0,
          }}>Full</button>
        )}
        {r.status === 'completed' && (
          <span style={{ fontSize: 13, color: dark ? '#475569' : '#94a3b8', flexShrink: 0 }}>
            Completed ✓
          </span>
        )}
      </div>
    </div>
  );
}
